function decodeManagedAgentExecutionMessage(
  value: unknown,
  path: string,
): ManagedAgentExecutionMessage {
  const source = strictRecord(
    value,
    [
      "requestId",
      "protocolVersion",
      "executionId",
      "generation",
      "commandId",
      "occurredAt",
      "messageType",
      "payload",
      "error",
    ],
    [
      "requestId",
      "protocolVersion",
      "executionId",
      "generation",
      "commandId",
      "occurredAt",
      "messageType",
    ],
    path,
  );
  const protocol = strictRecord(
    source.protocolVersion,
    ["major", "minor"],
    ["major", "minor"],
    `${path}/protocolVersion`,
  );
  const major = integer(protocol.major, 2, 2, `${path}/protocolVersion/major`);
  const minor = integer(protocol.minor, 0, 3, `${path}/protocolVersion/minor`);
  const message: {
    requestId: string;
    protocolVersion: Readonly<{ major: number; minor: number }>;
    executionId: string;
    generation: number;
    commandId: string;
    occurredAt: string;
    messageType: ManagedAgentExecutionMessage["messageType"];
    payload?: unknown;
    error?: ManagedAgentExecutionError;
  } = {
    requestId: identifier(source.requestId, `${path}/requestId`),
    protocolVersion: Object.freeze({ major, minor }),
    executionId: identifier(source.executionId, `${path}/executionId`),
    generation: integer(source.generation, 1, Number.MAX_SAFE_INTEGER, `${path}/generation`),
    commandId: identifier(source.commandId, `${path}/commandId`),
    occurredAt: dateTime(source.occurredAt, `${path}/occurredAt`),
    messageType: enumValue(
      source.messageType,
      [
        "Error",
        "Event",
        "InteractionRequest",
        "ArtifactCandidate",
        "Checkpoint",
        "Result",
        "Progress",
      ] as const,
      `${path}/messageType`,
    ),
  };
  if (source.payload !== undefined) message.payload = source.payload;
  if (source.error !== undefined) {
    const errorBody = strictRecord(
      source.error,
      [
        "code",
        "message",
        "retryable",
        "requiresNewExecution",
        "requiresUserAction",
        "canReconstructFromHistory",
        "canMoveWorker",
      ],
      [
        "code",
        "message",
        "retryable",
        "requiresNewExecution",
        "requiresUserAction",
        "canReconstructFromHistory",
        "canMoveWorker",
      ],
      `${path}/error`,
    );
    message.error = Object.freeze({
      code: boundedString(errorBody.code, 1, 128, `${path}/error/code`),
      message: boundedString(errorBody.message, 0, 4096, `${path}/error/message`),
      retryable: boolean(errorBody.retryable, `${path}/error/retryable`),
      requiresNewExecution: boolean(
        errorBody.requiresNewExecution,
        `${path}/error/requiresNewExecution`,
      ),
      requiresUserAction: boolean(errorBody.requiresUserAction, `${path}/error/requiresUserAction`),
      canReconstructFromHistory: boolean(
        errorBody.canReconstructFromHistory,
        `${path}/error/canReconstructFromHistory`,
      ),
      canMoveWorker: boolean(errorBody.canMoveWorker, `${path}/error/canMoveWorker`),
    });
  }
  if (message.messageType === "Error" && message.error === undefined)
    error("MISSING_FIELD", `${path}/error`);
  return Object.freeze(message);
}
